# A dynamic resource list handler, pseudocode
def list_resources():
    open_tickets = ticket_db.query("SELECT id, subject FROM tickets WHERE status = 'open'")
    return [
        {"uri": f"ticket://support/{t.id}", "name": t.subject, "mimeType": "text/plain"}
        for t in open_tickets
    ]

