def list_resources():
    active = oncall_db.query("SELECT engineer_id, name FROM shifts WHERE now() BETWEEN start_time AND end_time")
    return [
        {"uri": f"oncall://team-a/{s.engineer_id}", "name": s.name, "mimeType": "text/plain"}
        for s in active
    ]

